// Safe direct lookup function returning PROGMEM pointer without indirect pointer arrays
inline const uint16_t* getSpriteAiFrame(int animIdx, int frameIdx) {
  if (animIdx < 0 || animIdx >= SPRITE_AI_ANIMATION_COUNT) animIdx = 0;
  if (frameIdx < 0 || frameIdx >= SPRITE_AI_FRAME_COUNT) frameIdx = 0;
  switch (animIdx) {
    case 0:
      switch (frameIdx) {
        case 0: return luna_sprite_ai_anim0_frame_00;
        case 1: return luna_sprite_ai_anim0_frame_01;
        case 2: return luna_sprite_ai_anim0_frame_02;
        case 3: return luna_sprite_ai_anim0_frame_03;
      }
      break;
    case 1:
      switch (frameIdx) {
        case 0: return luna_sprite_ai_anim1_frame_00;
        case 1: return luna_sprite_ai_anim1_frame_01;
        case 2: return luna_sprite_ai_anim1_frame_02;
        case 3: return luna_sprite_ai_anim1_frame_03;
      }
      break;
    case 2:
      switch (frameIdx) {
        case 0: return luna_sprite_ai_anim2_frame_00;
        case 1: return luna_sprite_ai_anim2_frame_01;
        case 2: return luna_sprite_ai_anim2_frame_02;
        case 3: return luna_sprite_ai_anim2_frame_03;
      }
      break;
    case 3:
      switch (frameIdx) {
        case 0: return luna_sprite_ai_anim3_frame_00;
        case 1: return luna_sprite_ai_anim3_frame_01;
        case 2: return luna_sprite_ai_anim3_frame_02;
        case 3: return luna_sprite_ai_anim3_frame_03;
      }
      break;
    case 4:
      switch (frameIdx) {
        case 0: return luna_sprite_ai_anim4_frame_00;
        case 1: return luna_sprite_ai_anim4_frame_01;
        case 2: return luna_sprite_ai_anim4_frame_02;
        case 3: return luna_sprite_ai_anim4_frame_03;
      }
      break;
    case 5:
      switch (frameIdx) {
        case 0: return luna_sprite_ai_anim5_frame_00;
        case 1: return luna_sprite_ai_anim5_frame_01;
        case 2: return luna_sprite_ai_anim5_frame_02;
        case 3: return luna_sprite_ai_anim5_frame_03;
      }
      break;
  }
  return luna_sprite_ai_anim0_frame_00;
}

